// km formats meters as kilometers with German decimal comma.
func km(m float64) string { return germanFloat(m/1000, 1) }

// kmInt formats meters as whole kilometers with thousands separator.
func kmInt(m float64) string { return thousands(int(math.Round(m / 1000))) }

// thousands formats an integer with German thousands separators.
func thousands(n int) string {
	s := fmt.Sprint(n)
	neg := strings.HasPrefix(s, "-")
	s = strings.TrimPrefix(s, "-")
	for i := len(s) - 3; i > 0; i -= 3 {
		s = s[:i] + "." + s[i:]
	}
	if neg {
		return "−" + s
	}
	return s
}

func kmh(mps float64) string {
	if mps <= 0 {
		return "–"
	}
	return germanFloat(mps*3.6, 1)
}

func germanFloat(v float64, decimals int) string {
	s := fmt.Sprintf("%.*f", decimals, v)
	out := []byte(s)
	for i, c := range out {
		if c == '.' {
			out[i] = ','
		}
	}
	return string(out)
}

// duration formats seconds as h:mm:ss.
func duration(seconds float64) string {
	s := int(math.Round(seconds))
	return fmt.Sprintf("%d:%02d:%02d", s/3600, s/60%60, s%60)
}

// signedKm formats a km difference with sign, e.g. "+12" or "−3".
func signedKm(v float64) string {
	n := int(math.Round(v))
	switch {
	case n > 0:
		return fmt.Sprintf("+%d", n)
	case n < 0:
		return fmt.Sprintf("−%d", -n)
	}
	return "±0"
}

// hours formats seconds as h:mm for long totals.
func hours(seconds float64) string {
	m := int(math.Round(seconds / 60))
	return fmt.Sprintf("%d:%02d", m/60, m%60)
}

// localTime formats a UTC time on the activity's wall clock.
func localTime(t time.Time, offsetS int) string {
	if t.IsZero() {
		return "–"
	}
	return t.In(time.FixedZone("", offsetS)).Format("02.01.2006 15:04")
}

func orDash(v int) string {
	if v == 0 {
		return "–"
	}
	return fmt.Sprint(v)
}
